// Calculate provider security score
let providerScore = 0;
switch(emailProvider) {
  case 'protonmail': case 'tutanota': providerScore = 10; break;
  case 'startmail': case 'hushmail': providerScore = 8; break;
  case 'gmail': case 'outlook': providerScore = 4; break;
  case 'yahoo': case 'other-mainstream': providerScore = 2; break;
}

// Calculate encryption score
let encryptionScore = 0;
switch(encryptionUsage) {
  case 'always': encryptionScore = 20; break;
  case 'sensitive': encryptionScore = 15; break;
  case 'rarely': encryptionScore = 5; break;
  case 'never': encryptionScore = 0; break;
}

// Calculate security practices score
let securityScore = 0;
securityScore += twoFactorAuth ? 15 : 0;
switch(passwordStrength) {
  case 'strong': securityScore += 10; break;
  case 'medium': securityScore += 5; break;
  case 'weak': securityScore += 0; break;
}
securityScore += emailForwarding ? 5 : 0;

// Calculate risk from behaviors
let behaviorRisk = 0;
switch(publicWifiUsage) {
  case 'never': behaviorRisk = 0; break;
  case 'rarely': behaviorRisk = 5; break;
  case 'sometimes': behaviorRisk = 10; break;
  case 'often': behaviorRisk = 20; break;
}
behaviorRisk += Math.min(sensitiveEmails * 0.5, 15);

// Calculate total score (higher is better security)
const totalSecurity = providerScore + encryptionScore + securityScore;
const riskScore = Math.max(0, Math.min(100, 100 - totalSecurity + behaviorRisk));

// Determine risk level
let riskLevel = '';
if(riskScore <= 30) riskLevel = 'Low Risk';
else if(riskScore <= 60) riskLevel = 'Medium Risk';
else riskLevel = 'High Risk';

// Calculate encryption grade
let encryptionGrade = 'F';
if(encryptionScore >= 18) encryptionGrade = 'A';
else if(encryptionScore >= 12) encryptionGrade = 'B';
else if(encryptionScore >= 6) encryptionGrade = 'C';
else if(encryptionScore >= 2) encryptionGrade = 'D';

return { riskScore: Math.round(riskScore), riskLevel, encryptionGrade };
